package scaffold

import (
	"go/format"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// The fixtures are real handlers generated by v3.213.0 into a test project,
// copied verbatim: the repair anchors on exactly this text.
func repairFixture(t *testing.T, name string) string {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", "handler_repair", name))
	if err != nil {
		t.Fatalf("fixture: %v", err)
	}
	return strings.ReplaceAll(string(raw), "\r\n", "\n")
}

func mustFormat(t *testing.T, what, src string) {
	t.Helper()
	if _, err := format.Source([]byte(src)); err != nil {
		t.Fatalf("%s is not valid Go after the repair: %v", what, err)
	}
}

// Reproduced live before the fix: a second ordinary account printed and
// rewrote the first account's owned record through PDF and PATCH.
func TestRepairClosesAnOwnedHandlersSideDoors(t *testing.T) {
	src := repairFixture(t, "provider_note.go.txt")
	out, fixed, warn, pascal, col := repairHandlerSource(src)
	if pascal != "ProviderNote" || col != "user_id" {
		t.Fatalf("identified %q owned by %q", pascal, col)
	}
	if len(warn) > 0 {
		t.Errorf("warnings on an untouched generated file: %v", warn)
	}
	mustFormat(t, "the handler", out)

	if n := strings.Count(out, "authz.OwnsOr404(c, &item)"); n != 5 {
		t.Errorf("%d by-id handlers check the owner, want 5 (GetByID, PDF, Update, Patch, Delete)", n)
	}
	for _, want := range []string{
		`authz.ScopeToOwner(c, query, "user_id")`,
		`authz.ScopeToOwner(c, scope, "user_id")`,
		"query.FindInBatches(&rows, exportBatchSize",
		"var rows []models.ProviderNote",
		// An export with nothing in it is still a CSV with its header.
		"} else if !headerWritten {",
	} {
		if !strings.Contains(out, want) {
			t.Errorf("the repaired handler is missing %s", want)
		}
	}
	if n := strings.Count(out, "authz.ScopeToOwner("); n != 3 {
		t.Errorf("%d scoped queries, want 3 (List, Export, Bulk)", n)
	}
	if strings.Contains(out, "tx.Scan(&rows)") || strings.Contains(out, `Order("created_at desc")`) {
		t.Error("Export still reads through tx.Scan or sorts ahead of its paging key")
	}
	if len(fixed) != 2 {
		t.Errorf("reported %v", fixed)
	}

	again, fixedAgain, _, _, _ := repairHandlerSource(out)
	if again != out || len(fixedAgain) != 0 {
		t.Error("a second upgrade changed the handler again")
	}
}

// Every resource's CSV export was empty, owned or not.
func TestRepairFixesExportOnASharedResource(t *testing.T) {
	out, fixed, warn, _, col := repairHandlerSource(repairFixture(t, "journal_entry.go.txt"))
	if col != "" || strings.Contains(out, "authz.") {
		t.Error("a shared resource grew ownership checks")
	}
	if len(warn) > 0 || len(fixed) != 1 {
		t.Errorf("fixed %v, warned %v", fixed, warn)
	}
	if strings.Contains(out, "tx.Scan(&rows)") {
		t.Error("Export still reads through tx.Scan")
	}
	mustFormat(t, "the handler", out)
}

func TestRepairLeavesAnEditedHandlerAloneAndSaysSo(t *testing.T) {
	src := repairFixture(t, "provider_note.go.txt")
	// Somebody rewrote PDF's lookup: the guard has nowhere recognisable to go.
	src = strings.Replace(src,
		"func (h *ProviderNoteHandler) PDF(c *gin.Context) {\n\tid := c.Param(\"id\")\n\n\tvar item models.ProviderNote\n\tif err := h.scoped(c).Preload(\"User\").First(&item, \"id = ?\", id).Error; err != nil {",
		"func (h *ProviderNoteHandler) PDF(c *gin.Context) {\n\tid := c.Param(\"id\")\n\n\tvar item models.ProviderNote\n\tif err := loadNote(h.DB, id, &item); err != nil {", 1)
	_, _, warn, _, _ := repairHandlerSource(src)
	if len(warn) != 1 || !strings.Contains(warn[0], "PDF") {
		t.Errorf("an unpatchable PDF was not reported: %v", warn)
	}
}

func TestRepairImporterStampsTheOwnerAndStopsCreatingUsers(t *testing.T) {
	src := repairFixture(t, "provider_note_import.go.txt")
	out, fixed, warn := repairImportSource(src, map[string]string{"ProviderNote": "user_id"}, "ledger/apps/api")
	if len(warn) > 0 {
		t.Errorf("warnings: %v", warn)
	}
	mustFormat(t, "the importer", out)
	for _, want := range []string{
		"go h.runImportProviderNote(job.ID, tmpPath, authz.CurrentUserID(c), authz.IsAdmin(c))",
		"runImportProviderNote(jobID, tmpPath string, ownerID string, canAssignOwner bool)",
		"item.UserID = ownerID",
		`get(rec, "user"); ok && v != "" && canAssignOwner {`,
		`"ledger/apps/api/internal/authz"`,
		`fmt.Sprintf("no user with email %q", v)`,
	} {
		if !strings.Contains(out, want) {
			t.Errorf("the repaired importer is missing %s", want)
		}
	}
	if strings.Contains(out, "h.DB.Create(&rel)") {
		t.Error("the importer still creates users")
	}
	if len(fixed) != 2 {
		t.Errorf("reported %v", fixed)
	}
	again, fixedAgain, _ := repairImportSource(out, map[string]string{"ProviderNote": "user_id"}, "ledger/apps/api")
	if again != out || len(fixedAgain) != 0 {
		t.Error("a second upgrade changed the importer again")
	}

	// Not owned: only the user creation goes.
	shared, _, _ := repairImportSource(src, map[string]string{}, "ledger/apps/api")
	if strings.Contains(shared, "canAssignOwner") || strings.Contains(shared, "h.DB.Create(&rel)") {
		t.Error("a shared importer grew owner logic, or still creates users")
	}
}

func TestRepairWorkflowChecksTheOwner(t *testing.T) {
	src := `package services

import (
	"fmt"

	"github.com/gin-gonic/gin"
	"gorm.io/gorm"

	"shop/apps/api/internal/models"
)

func TransitionTicket(db *gorm.DB, c *gin.Context, id, action string, can func(string) bool) (*models.Ticket, error) {
	var item models.Ticket
	if err := db.First(&item, "id = ?", id).Error; err != nil {
		return nil, err
	}

	from := item.Status
	return &item, fmt.Errorf("%s", from)
}
`
	out, fixed, warn := repairWorkflowSource(src, map[string]string{"Ticket": "user_id"}, "shop/apps/api")
	if len(warn) > 0 || len(fixed) != 1 {
		t.Fatalf("fixed %v, warned %v", fixed, warn)
	}
	mustFormat(t, "the workflow service", out)
	if !strings.Contains(out, "item.GetOwnerID() != authz.CurrentUserID(c)") || !strings.Contains(out, `"shop/apps/api/internal/authz"`) {
		t.Error("Transition does not check the owner")
	}
	if same, _, _ := repairWorkflowSource(src, map[string]string{}, "shop/apps/api"); same != src {
		t.Error("an unowned workflow was changed")
	}
}
